#include <stdio.h>
int main(void) {
    int x, y;
    if (scanf("%d", &x) != 1) return 1;
    if (x <= 0) y = x + 1;
    else if (x <= 3) y = 1;
    else y = x;
    printf("%d\n", y);
    return 0;
}

