北工大-C-样题-五-01.参考答案:
#include <stdio.h>

int main(void)
{
    for (int n = 100; n <= 999; n++)
    {
        int a = n / 100;
        int b = n / 10 % 10;
        int c = n % 10;
        if (a*a*a + b*b*b + c*c*c == n)
            printf("%d\n", n);
    }
    return 0;
}

